class Command(BaseCommand):
    help = "مخزن ذینفعان سایپا یدک را با نسخه‌ی نهایی (۱۹۰ ردیف واقعی، درون/برون‌سازمانی) پاک و جایگزین می‌کند."

    def handle(self, *args, **options):
        Stakeholder.objects.all().delete()
        for row in ROWS:
            Stakeholder.objects.create(**row)
        self.stdout.write(self.style.SUCCESS(f"ثبت شد: {len(ROWS)} ذینفع."))
